import{_ as e,o as a,c as o,af as s}from"./chunks/framework._zKnALF5.js";const g=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"en/guide/getting-started.md","lastUpdated":null}'),r={name:"en/guide/getting-started.md"};function n(i,t,d,h,l,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p><strong>xymj-colyseus-server</strong> is an <strong>opinionated</strong> Colyseus server in <strong>TypeScript + Express</strong>: JWT, matchmaker rooms, frame-sync game rooms, chat rooms, and related conventions ship together. Below is the <strong>shortest path</strong> to run it locally; use the sidebar for deeper topics.</p><h2 id="_1-clone-install" tabindex="-1">1. Clone &amp; install <a class="header-anchor" href="#_1-clone-install" aria-label="Permalink to &quot;1. Clone &amp; install&quot;">​</a></h2><p>In the <strong><code>xymj-colyseus-server</code></strong> repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>See <a href="/en/guide/installation.html">Installation</a> for Node / MySQL / Redis requirements.</p><h2 id="_2-configure-run" tabindex="-1">2. Configure &amp; run <a class="header-anchor" href="#_2-configure-run" aria-label="Permalink to &quot;2. Configure &amp; run&quot;">​</a></h2><p>Copy and edit <code>.env.development</code> (MySQL, <strong>Redis</strong> — needed for matchmaking / chat queues — <code>JWT_SECRET</code>, etc.), then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Default <strong><code>http://localhost:2567</code></strong> (port from <code>PORT</code>).</p><h2 id="_3-verify-http-static-pages" tabindex="-1">3. Verify HTTP &amp; static pages <a class="header-anchor" href="#_3-verify-http-static-pages" aria-label="Permalink to &quot;3. Verify HTTP &amp; static pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>URL</th></tr></thead><tbody><tr><td>Swagger</td><td><code>http://localhost:2567/api-docs</code></td></tr><tr><td>Static intro</td><td><code>http://localhost:2567/</code></td></tr></tbody></table><p>Use Swagger or your login API to obtain a <strong><code>token</code></strong>; Colyseus <code>join</code> / <code>joinOrCreate</code> options must carry it (see <a href="/en/guide/jwt-room-auth.html">JWT &amp; room authentication</a> — full text in Chinese until translated).</p><h2 id="_4-try-matchmaking-in-the-browser" tabindex="-1">4. Try matchmaking in the browser <a class="header-anchor" href="#_4-try-matchmaking-in-the-browser" aria-label="Permalink to &quot;4. Try matchmaking in the browser&quot;">​</a></h2><p>Open <strong><code>http://localhost:2567/MatchmakingDemo.html</code></strong>, set the server URL and JWT, open multiple tabs to exercise <strong><code>match:find</code> → <code>match:found</code> → join <code>game_room</code></strong>. Parameters and scaling rules: <a href="/en/scenarios/multi-scale-matchmaking.html">Multi-scale matchmaking</a> (stub → links to Chinese).</p><h2 id="_5-where-to-go-next" tabindex="-1">5. Where to go next <a class="header-anchor" href="#_5-where-to-go-next" aria-label="Permalink to &quot;5. Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Doc</th></tr></thead><tbody><tr><td>Environment variables</td><td><a href="/en/guide/configuration.html">Configuration</a></td></tr><tr><td>Room names &amp; layout</td><td><a href="/en/guide/project-structure.html">Project structure</a></td></tr><tr><td>Match / Party message names</td><td><a href="/en/rooms/matchmaking.html">Matchmaking</a>, <a href="/en/reference/protocol.html">Protocol</a></td></tr><tr><td>Unity / Cocos / Godot</td><td><a href="/en/engine/overview.html">Engine overview</a></td></tr><tr><td>Scenario pickers</td><td><a href="/en/scenarios/overview.html">Scenarios overview</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Chinese mirror</p><p>Most deep-dive pages are still <strong>Simplified Chinese only</strong>. Each English stub links to the matching <strong>中文</strong> page at the same path without <code>/en/</code>.</p></div>',18)])])}const m=e(r,[["render",n]]);export{g as __pageData,m as default};
